const config = {
  configVersion: '1.0.0',
  botId: '',
  botUsername: '',
  operatorUserId: '',
  operatorChatId: '',
  ingressPolicy: {
    expectedUpdateType: 'message',
    requirePrivateChat: true,
    requireHumanSender: true,
    supportedKinds: ['voice', 'text'],
    maxTextCharacters: 8000,
    maxFileIdCharacters: 1024,
    maxFileUniqueIdCharacters: 256,
    maxSanitizedMessageBytes: 32768
  },
  retryPolicy: { stageMaxAttempts: 5, blindWriteRetries: false },
  priorityPolicy: { unknownDefault: 'normal', criticalRequiresConfirmation: true },
  phase: '1B'
};
const positiveId = value => typeof value === 'string' && /^[1-9][0-9]{0,14}$/.test(value) && Number.isSafeInteger(Number(value));
if (!config.configVersion || !config.botUsername ||
    !positiveId(config.botId) || !positiveId(config.operatorUserId) || !positiveId(config.operatorChatId) ||
    config.ingressPolicy.expectedUpdateType !== 'message' ||
    config.ingressPolicy.requirePrivateChat !== true || config.ingressPolicy.requireHumanSender !== true ||
    JSON.stringify(config.ingressPolicy.supportedKinds) !== JSON.stringify(['voice', 'text']) ||
    !Number.isInteger(config.retryPolicy.stageMaxAttempts) ||
    config.retryPolicy.stageMaxAttempts < 1 || config.retryPolicy.stageMaxAttempts > 20 ||
    config.retryPolicy.blindWriteRetries !== false) {
  throw new Error('Required ticket intake configuration is missing or invalid');
}
return [{ json: config }];
